head.b:skin:
/*<Variable name="font.family" description="Font Family" type="font" default="Tajawal, sans-serif"/>*/
/*<Variable name="color.primary" description="Primary Color" type="color" default="#0D47A1"/>*/
/*<Variable name="color.secondary" description="Secondary Color" type="color" default="#EF6C00"/>*/
/*<Variable name="color.bg.light" description="Background (Light)" type="color" default="#FFFFFF"/>*/
/*<Variable name="color.bg.dark" description="Background (Dark)" type="color" default="#0B0F19"/>*/
/*<Variable name="color.text.light" description="Text (Light)" type="color" default="#111111"/>*/
/*<Variable name="color.text.dark" description="Text (Dark)" type="color" default="#E8EAF6"/>*/

:root {
  --font-family: $(font.family);
  --color-primary: $(color.primary);
  --color-secondary: $(color.secondary);
  --color-bg: $(color.bg.light);
  --color-text: $(color.text.light);
  --color-border: #e0e0e0;
  --card-bg: #fff;
}
html.theme-dark {
  --color-bg: $(color.bg.dark);
  --color-text: $(color.text.dark);
  --color-border: #2a2a2a;
  --card-bg: #1f2937;
}
body { font-family: var(--font-family); background-color: var(--color-bg); color: var(--color-text); margin: 0; line-height: 1.7; font-size: 16px; transition: background-color .2s; }
a { color: var(--color-primary); text-decoration: none; }
img { max-width: 100%; height: auto; }
.container { max-width: 1200px; margin: 0 auto; padding: 0 15px; }
.header-container { background-color: var(--card-bg); padding: 15px 0; border-bottom: 1px solid var(--color-border); }
.header-container .container { display: flex; justify-content: space-between; align-items: center; }
.main-container { display: flex; flex-wrap: wrap; gap: 20px; padding: 20px 0; }
.content-area { flex: 1 1 70%; min-width: 0; }
.sidebar-area { flex: 1 1 25%; min-width: 0; }
.post-card { background-color: var(--card-bg); border: 1px solid var(--color-border); margin-bottom: 20px; border-radius: 5px; overflow: hidden; }
.post-card img { width: 100%; display: block; }
.post-card-content { padding: 20px; }
.post-card-title a { font-size: 1.6em; color: var(--color-text); font-weight: bold; text-decoration: none; }
.footer-container { background-color: var(--card-bg); padding: 20px; text-align: center; border-top: 1px solid var(--color-border); margin-top: 20px; }
.theme-toggle { cursor: pointer; padding: 8px 12px; border: 1px solid var(--color-border); border-radius: 5px; background-color: var(--card-bg); color: var(--color-text); }
.news-ticker { display: flex; background-color: var(--card-bg); border: 1px solid var(--color-border); margin: 15px 0; overflow: hidden; }
.ticker-title { background-color: var(--color-secondary); color: #fff; padding: 10px 15px; font-weight: bold; white-space: nowrap; }
.ticker-content { overflow: hidden; position: relative; flex-grow: 1; }
.ticker-content ul { list-style: none; padding: 0; margin: 0; display: flex; position: absolute; white-space: nowrap; animation: ticker-scroll 40s linear infinite; }
.ticker-content ul:hover { animation-play-state: paused; }
.ticker-content ul li a { display: block; padding: 10px 15px; color: var(--color-text); }
@keyframes ticker-scroll { 0% { transform: translateX(100%); } 100% { transform: translateX(-100%); } }

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
    // Dark Mode Toggle
    const themeToggle = document.getElementById('theme-toggle');
    if(themeToggle) {
        const htmlEl = document.documentElement;
        const currentTheme = localStorage.getItem('theme');
        if (currentTheme) {
            htmlEl.classList.add(currentTheme);
        }
        themeToggle.addEventListener('click', () => {
            htmlEl.classList.toggle('theme-dark');
            let theme = '';
            if (htmlEl.classList.contains('theme-dark')) {
                theme = 'theme-dark';
            }
            localStorage.setItem('theme', theme);
        });
    }

    // Breaking News Ticker
    const tickerSection = document.getElementById('news-ticker');
    if (tickerSection) {
        fetch('/feeds/posts/default/-/عاجل?alt=json&amp;max-results=7')
            .then(response => response.json())
            .then(data => {
                const entries = data.feed.entry || [];
                if (entries.length > 0) {
                    let listItems = '';
                    entries.forEach(post => {
                        const postUrl = post.link.find(l => l.rel === 'alternate').href;
                        const postTitle = post.title.$t;
                        listItems += `<li><a href="${postUrl}">${postTitle}</a></li>`;
                    });

                    const tickerHTML = `
                        <div class="news-ticker">
                            <div class="ticker-title">عاجل</div>
                            <div class="ticker-content">
                                <ul>${listItems}</ul>
                            </div>
                        </div>
                    `;
                    tickerSection.innerHTML = tickerHTML;
                }
            })
            .catch(error => console.error("Error fetching breaking news:", error));
    }
});
//
